#include <stdio.h>

int main() {
    int marks[6] = {78, 92, 65, 88, 71, 84};
    int n = 6;
    int sum = 0;
    int max = marks[0];
    int min = marks[0];

    for (int i = 0; i < n; i++) {
        sum += marks[i];
        if (marks[i] > max) {
            max = marks[i];
        }
        if (marks[i] < min) {
            min = marks[i];
        }
    }

    float average = (float)sum / n;

    printf("Sum: %d\n", sum);
    printf("Max: %d\n", max);
    printf("Min: %d\n", min);
    printf("Average: %.2f\n", average);
    return 0;
}

