#include <stdio.h>

int main() {
    int marks[6] = {78, 92, 65, 88, 71, 84};
    int maxPos = 0;
    int minPos = 0;

    for (int i = 1; i < 6; i++) {
        if (marks[i] > marks[maxPos]) {
            maxPos = i;
        }
        if (marks[i] < marks[minPos]) {
            minPos = i;
        }
    }
    printf("Topper: roll %d with %d\n", maxPos + 1, marks[maxPos]);
    printf("Lowest: roll %d with %d\n", minPos + 1, marks[minPos]);
    return 0;
}

